const $ = s => document.querySelector(s);
const $$ = s => [...document.querySelectorAll(s)];
const state = { data:null, auth:null, view:'dashboard', settingsTab:'general', exerciseSourceMode:'custom', catalogResults:[], historyRows:[], selectedHistoryEntry:null, backupStatus:null, backupFiles:[], versionInfo:null, updateCheck:null, updatePolling:false, scoreResults:[], gameResults:[], achievementResult:null, inventoryResult:null, shopResult:null, inventoryFilter:'all', shopFilter:'all', shopSearch:'', selectedGameItem:null };
const titles = { dashboard:'Twój progres', history:'Historia zmian', chart:'Wykres progresu', exercises:'Ćwiczenia', character:'Postać', inventory:'Ekwipunek', shop:'Sklep', achievements:'Osiągnięcia', settings:'Ustawienia' };
const modeLabel = { direct:'Wpis bezpośredni', plates:'Sztanga / krążki', steps:'Maszyna / stopnie' };

async function api(url, options={}) {
  const {headers={},...requestOptions}=options;
  let res;
  try{res=await fetch(url,{...requestOptions,headers:{'Content-Type':'application/json',...headers}});}
  catch{throw new Error('Brak połączenia z serwerem CRESCI. Sprawdź, czy usługa jest uruchomiona, i spróbuj ponownie.');}
  const data = await res.json();
  if (!res.ok) {if(res.status===401&&data.code==='AUTH_REQUIRED')await showAuth();throw new Error(data.error || 'Wystąpił błąd.');}
  return data;
}
function esc(v=''){ return String(v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c])); }
function fmt(v){ return v == null ? '—' : Number(v).toLocaleString('pl-PL',{maximumFractionDigits:2}); }
function dateFmt(v){ if(!v)return '—'; return new Date(`${v}T12:00:00`).toLocaleDateString('pl-PL',{day:'2-digit',month:'short',year:'numeric'}); }
function dateTimeFmt(v){if(!v)return 'jeszcze nigdy';return new Date(v).toLocaleString('pl-PL',{dateStyle:'medium',timeStyle:'short'});}
function toast(message){ const el=$('#toast'); el.textContent=message; el.classList.add('show'); setTimeout(()=>el.classList.remove('show'),2600); }
function achievementMessage(items=[]){return items.length?items.map(item=>`Osiągnięcie odblokowane: „${item.name}” +${item.rewardPr} PR`).join(' · '):'';}
function authInitial(name=''){return String(name).trim().charAt(0).toUpperCase()||'C';}
function applyAuthenticatedUser(user){state.auth={authenticated:true,user};$('#authScreen').hidden=true;document.body.classList.remove('auth-locked');$('.sidebar').inert=false;$('main').inert=false;$('#accountName').textContent=user.name;$('#accountAvatar').textContent=authInitial(user.name);$('#accountAvatar').style.setProperty('--user-color',user.color);$('#accountSettingsText').textContent=`Zalogowano jako ${user.name}. Usunięcie konta kasuje wyłącznie dane tego użytkownika.`;}
function setupAuthMarkup(){return `<h1>Utwórz pierwszego użytkownika</h1><p>To pierwsze uruchomienie CRESCI. Nazwa jest wymagana, a hasło możesz ustawić opcjonalnie.</p><form class="auth-form" id="firstUserForm"><label>Nazwa użytkownika<input name="name" minlength="2" maxlength="40" required autofocus autocomplete="nickname" placeholder="np. Marek"></label><label>Kolor profilu<input name="color" type="color" value="#ff5d45"></label><label>Hasło <small>(opcjonalne)</small><input name="password" type="password" maxlength="256" autocomplete="new-password"></label><label>Powtórz hasło<input name="password_repeat" type="password" maxlength="256" autocomplete="new-password"></label><button class="primary" type="submit">Utwórz konto i rozpocznij</button></form>`;}
function chooserAuthMarkup(users){return `<h1>Wybierz użytkownika</h1><p>Wybierz swoje konto, aby przejść do CRESCI.</p><div class="user-picker">${users.map(user=>`<button class="user-choice" type="button" data-login-user="${user.id}" style="--user-color:${esc(user.color)}"><span class="user-choice-avatar">${esc(authInitial(user.name))}</span><span><strong>${esc(user.name)}</strong><small>${user.password_required?'Konto chronione hasłem':'Bez hasła'}</small></span><span>${user.password_required?'⌑':'→'}</span></button>`).join('')}</div><button class="secondary auth-add-user" id="authAddUser" type="button">＋ Dodaj nowego użytkownika</button>`;}
function additionalUserMarkup(){return setupAuthMarkup().replace('Utwórz pierwszego użytkownika','Dodaj nowego użytkownika').replace('To pierwsze uruchomienie CRESCI. Nazwa jest wymagana, a hasło możesz ustawić opcjonalnie.','Utwórz kolejne konto CRESCI. Hasło nadal jest opcjonalne.').replace('Utwórz konto i rozpocznij','Dodaj konto i rozpocznij')+`<button class="auth-back" id="authBack" type="button">← Wróć do wyboru użytkownika</button>`;}
function passwordAuthMarkup(user){return `<h1>Witaj, ${esc(user.name)}</h1><p>To konto jest chronione hasłem.</p><form class="auth-form" id="loginForm"><input name="user_id" type="hidden" value="${user.id}"><label>Hasło<input name="password" type="password" required autofocus autocomplete="current-password"></label><button class="primary" type="submit">Zaloguj się</button></form><button class="auth-back" id="authBack" type="button">← Wróć do wyboru użytkownika</button>`;}
async function completeAuth(auth){applyAuthenticatedUser(auth.user);await load();const driveResult=new URLSearchParams(location.search).get('drive');if(driveResult){switchView('settings');switchSettingsTab('backup');toast(driveResult==='connected'?'Google Drive został połączony.':driveResult==='error'?'Nie udało się połączyć z Google. Spróbuj ponownie; jeśli błąd wróci, sprawdź terminal CRESCI.':'Łączenie z Google Drive anulowane.');history.replaceState({},'',location.pathname);}}
function bindAuthRegistration(){const form=$('#firstUserForm');if(!form)return;form.onsubmit=async event=>{event.preventDefault();const button=event.currentTarget.querySelector('button[type="submit"]');try{button.disabled=true;const auth=await api('/api/auth/register',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(event.currentTarget)))});await completeAuth(auth);}catch(error){toast(error.message)}finally{button.disabled=false;}};}
async function showAuth(){const status=await api('/api/auth/status');state.auth=status;state.data=null;document.body.classList.add('auth-locked');$('.sidebar').inert=true;$('main').inert=true;$('#authScreen').hidden=false;const content=$('#authContent');content.innerHTML=status.setup_required?setupAuthMarkup():chooserAuthMarkup(status.users||[]);if(status.authenticated){await completeAuth(status);return status;}bindAuthRegistration();content.onclick=async event=>{if(event.target.closest('#authAddUser')){content.innerHTML=additionalUserMarkup();bindAuthRegistration();$('#authBack').onclick=()=>showAuth().catch(error=>toast(error.message));return;}const button=event.target.closest('[data-login-user]');if(!button)return;const user=status.users.find(item=>item.id===Number(button.dataset.loginUser));if(!user)return;if(user.password_required){content.innerHTML=passwordAuthMarkup(user);$('#authBack').onclick=()=>showAuth().catch(error=>toast(error.message));$('#loginForm').onsubmit=submitLogin;return;}try{await completeAuth(await api('/api/auth/login',{method:'POST',body:JSON.stringify({user_id:user.id,password:''})}));}catch(error){toast(error.message)}};return status;}
async function submitLogin(event){event.preventDefault();const button=event.currentTarget.querySelector('button[type="submit"]');try{button.disabled=true;await completeAuth(await api('/api/auth/login',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(event.currentTarget)))}));}catch(error){toast(error.message)}finally{button.disabled=false;}}
async function load(){ state.data=await api('/api/bootstrap'); renderAll(); await Promise.all([renderScores(),renderGame()]); }
function renderAll(){ renderExercises(); renderSelects(); renderExerciseList(); renderScoreSettings(); renderGameSettings(); }
function renderExercises(){ const q=$('#exerciseSearch').value.toLowerCase(); const list=state.data.exercises.filter(e=>(e.name+' '+e.category).toLowerCase().includes(q)); const plates=v=>v?`<div class="plate-info">Krążki / stopień: <strong>${esc(v)}</strong></div>`:'<div class="plate-info empty-plates">Brak danych o krążkach</div>'; $('#exerciseGrid').innerHTML=list.length?list.map(e=>{const weights=e.profile_weights||[];return`<article class="exercise-card"><span class="category">${esc(e.category.toUpperCase())}</span><h3>${esc(e.name)}</h3><div class="dual-weights">${weights.map(item=>`<div class="profile-weight"><span class="profile-name"><i style="background:${esc(item.color)}"></i>${esc(item.name)}</span><div class="weight">${fmt(item.weight)} <small>kg</small></div>${plates(item.plates_or_steps)}<div class="last-date">${item.performed_at?dateFmt(item.performed_at):'Brak wpisów'}</div></div>`).join('')}</div><div class="card-actions">${weights.map(item=>`<button class="profile-add" data-entry-exercise="${e.id}" data-entry-profile="${item.profile_id}">+ ${esc(item.name)}</button>`).join('')}</div></article>`;}).join(''):'<div class="empty">Brak ćwiczeń pasujących do wyszukiwania.</div>'; }
function options(items, allLabel){ return `${allLabel?`<option value="">${allLabel}</option>`:''}${items.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}`; }
function renderSelects(){ const ps=options(state.data.profiles),es=options(state.data.exercises),archived=state.data.archived_exercises||[]; for(const id of ['entryProfile','exerciseCreator','historyProfile','chartProfile']){const select=$(`#${id}`);select.innerHTML=ps;select.disabled=true;} $('#entryExercise').innerHTML=es; $('#historyExercise').innerHTML=`<option value="">Wszystkie ćwiczenia</option>${state.data.exercises.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}${archived.length?`<optgroup label="Usunięte ćwiczenia">${archived.map(x=>`<option value="${x.id}">${esc(x.name)} (usunięte)</option>`).join('')}</optgroup>`:''}`; $('#chartExercise').innerHTML=`<option value="all">Indeks całego planu</option>${es}`; }
function renderExerciseList(){ $('#exerciseList').innerHTML=state.data.exercises.map(e=>`<article class="exercise-list-item"><div><h3>${esc(e.name)}</h3><small>${esc(e.category)} · ${Number(e.entry_count)||0} ${Number(e.entry_count)===1?'wpis':'wpisów'}</small></div><small>${modeLabel[e.load_mode]}</small><small>Skok: ${fmt(e.step_size)} kg${e.bar_weight?` · gryf ${fmt(e.bar_weight)} kg`:''}</small><div class="exercise-list-actions"><button class="text-button" data-edit-exercise="${e.id}">Edytuj</button><button class="delete-text-button" data-delete-exercise="${e.id}">Usuń</button></div></article>`).join(''); }

function renderScoreSettings(){const rows=state.data.score_settings||[];$('#scoreSettingsList').innerHTML=rows.map(item=>`<div class="score-setting-row" data-score-setting="${item.user_id}"><div class="score-setting-user"><i style="background:${item.color}"></i><strong>${esc(item.user_name)}</strong></div><label class="score-switch"><input type="checkbox" data-score-enabled ${Number(item.enabled)?'checked':''}><span></span><b>${Number(item.enabled)?'ON':'OFF'}</b></label><label class="score-goal">Cel / tydzień<select data-score-goal>${[1,2,3,4,5,6,7].map(value=>`<option value="${value}" ${Number(item.weekly_goal)===value?'selected':''}>${value}</option>`).join('')}</select></label></div>`).join('');}
async function renderScores(){const enabled=(state.data.score_settings||[]).some(item=>Number(item.enabled));if(!enabled){state.scoreResults=[];$('#scoreSection').hidden=true;$('#scoreGrid').innerHTML='';if($('#scoreDialog').open)$('#scoreDialog').close();return;}try{state.scoreResults=await api('/api/cresci-score');$('#scoreSection').hidden=!state.scoreResults.length;$('#scoreGrid').innerHTML=state.scoreResults.map(score=>{const arrow=score.change>0?'↑':score.change<0?'↓':'→',changeClass=score.change>0?'up':score.change<0?'down':'same';return`<button class="score-card" type="button" data-score-user="${score.user_id}" style="--profile-color:${esc((state.data.profiles.find(p=>p.id===score.user_id)||{}).color||'#ff5d45')}"><span class="score-card-user">${esc(score.user_name)}</span><span class="score-value"><strong>${score.score}</strong><small>/100</small></span><span class="score-change ${changeClass}">${arrow} ${Math.abs(score.change)} względem poprzednich 30 dni</span><span class="score-explanation">${esc(score.explanation)}</span><span class="score-more">Zobacz szczegóły →</span></button>`;}).join('');}catch(error){$('#scoreSection').hidden=true;toast(error.message);}}
function openScoreDetails(userId){const score=state.scoreResults.find(item=>item.user_id===userId);if(!score)return;$('#scoreDialogTitle').textContent=`CRESCI Score — ${score.user_name}`;const order=['strength','regularity','coverage','continuity'];$('#scoreDialogContent').innerHTML=`<div class="score-detail-total"><strong>${score.score}<small>/100</small></strong><span>${score.change>0?'↑':score.change<0?'↓':'→'} ${Math.abs(score.change)} pkt · ${score.period.start} – ${score.period.end}</span></div><div class="score-breakdown">${order.map(key=>{const item=score.categories[key],width=item.max?item.score/item.max*100:0;return`<article><div><strong>${esc(item.label)}</strong><span>${item.score}/${item.max}</span></div><div class="score-bar"><i style="width:${width}%"></i></div><small>${item.change>0?'+':''}${item.change} pkt względem poprzedniego okresu</small></article>`;}).join('')}</div><p class="score-detail-explanation">${esc(score.explanation)}</p><details class="score-method"><summary>Jak liczony jest wynik?</summary>${order.map(key=>`<p><strong>${esc(score.categories[key].label)}:</strong> ${esc(score.methodology[key])}</p>`).join('')}<p>Okres porównawczy: ${esc(score.previous_period.start)} – ${esc(score.previous_period.end)}. Algorytm v${score.version}, bez AI i losowości.</p></details>`;$('#scoreDialog').showModal();}

const AVATAR_ASSET_ROOT='/assets/avatars/v4-production',AVATAR_CACHE_VERSION='4.1';
let spriteManifest={version:'v4-production',packId:'cresci-avatar-hd-creator-shop-v4-production',root:AVATAR_ASSET_ROOT,format:'png',defaultResolution:'runtime',compactResolution:'compact',layerOrder:['back','body','eyes','hair','bottom','top','shoes','headwear','accessories'],variants:{runtime:{width:512,height:768,anchor:{name:'feet-center',x:256,y:758}},compact:{width:256,height:384,anchor:{name:'feet-center',x:128,y:379}}},assets:[]};
let creatorCatalog=null,avatarShopCatalog=null,avatarPngPaths=new Set();
const legacyCreatorAliases={skin_tone:{light:'fair',warm:'tan'},hair_color:{brown:'dark_brown'},hairstyle:{male:{short:'short_textured',fade:'undercut',long:'side_swept',bun:'short_textured'},female:{short:'bob',fade:'bob',bun:'high_bun'}}};
function normalizedCreatorAvatar(item={}){const gender=item.gender==='male'?'male':'female';return{...item,gender,skin_tone:legacyCreatorAliases.skin_tone[item.skin_tone]||item.skin_tone||creatorCatalog?.defaults?.[gender]?.skin||'fair',eye_color:item.eye_color||creatorCatalog?.defaults?.[gender]?.eyes||'brown',hairstyle:legacyCreatorAliases.hairstyle[gender][item.hairstyle]||item.hairstyle||creatorCatalog?.defaults?.[gender]?.hairStyle||(gender==='male'?'short_textured':'ponytail'),hair_color:legacyCreatorAliases.hair_color[item.hair_color]||item.hair_color||creatorCatalog?.defaults?.[gender]?.hairColor||'dark_brown'};}
async function loadSpriteManifest(){try{const urls=[`${AVATAR_ASSET_ROOT}/manifest.json?v=${AVATAR_CACHE_VERSION}`,`${AVATAR_ASSET_ROOT}/creator/catalog.json?v=${AVATAR_CACHE_VERSION}`,`${AVATAR_ASSET_ROOT}/shop/catalog.json?v=${AVATAR_CACHE_VERSION}`],responses=await Promise.all(urls.map(url=>fetch(url,{cache:'no-store'})));if(responses.some(response=>!response.ok))throw new Error();const [manifest,creator,shop]=await Promise.all(responses.map(response=>response.json())),runtime=manifest.variants?.runtime,compact=manifest.variants?.compact;if(!runtime?.width||!runtime?.height||!compact?.width||!compact?.height||manifest.packId!=='cresci-avatar-hd-creator-shop-v4-production')throw new Error();spriteManifest={...manifest,version:'v4-production',root:AVATAR_ASSET_ROOT,format:'png',compactResolution:'compact'};creatorCatalog=creator;avatarShopCatalog=shop;avatarPngPaths=new Set(manifest.assets.filter(asset=>asset.format==='png').map(asset=>asset.path));configureAvatarCreator();}catch{console.warn('Nie udało się wczytać paczki avatara v4-production. Używam kontraktu wbudowanego.');}}
function versionedAvatarUrl(path){return path?`${spriteManifest.root}/${path}?v=${AVATAR_CACHE_VERSION}`:null;}
function creatorLayerPath(layer,item,resolution){if(!creatorCatalog)return null;const avatar=normalizedCreatorAvatar(item),variants=creatorCatalog.variantsByResolution?.[resolution]?.[avatar.gender];if(layer==='body')return variants?.body?.[avatar.skin_tone]?.png||null;if(layer==='eyes')return variants?.eyes?.[avatar.eye_color]?.png||null;if(layer==='hair')return variants?.hair?.[avatar.hairstyle]?.[avatar.hair_color]?.png||null;return null;}
const avatarFieldByLayer={back:'back_style',bottom:'bottom_style',top:'top_style',shoes:'shoes_style',headwear:'headwear',accessories:'accessory'};
const avatarAssetAliases={cresci_tank:'cresci_training_top',black_tee:'cresci_training_top',orange_hoodie:'orange_pullover_hoodie',power_crop:'black_performance_tank',training_shorts:'cresci_training_bottom',leggings:'cresci_training_bottom',cargo_shorts:'camo_cargo_pants',power_joggers:'black_elite_joggers',trainers:'cresci_runners',high_tops:'black_shadow_hightops',orange_lifters:'orange_utility_boots',legend_lifters:'cresci_runners',cap:'cresci_cap',beanie:'red_knit_beanie',wrist_wraps:'cresci_wristbands',lifting_belt:'black_utility_belt',gym_chain:'gold_power_chain'};
function itemLayerPath(layer,item,resolution){const avatar=normalizedCreatorAvatar(item),value=item[avatarFieldByLayer[layer]];if(!value||value==='none')return null;const assetName=avatarAssetAliases[value]||value,catalogItem=avatarShopCatalog?.items?.find(entry=>entry.gender===avatar.gender&&entry.slot===layer&&(entry.contentId===value||entry.assets?.[resolution]?.png?.endsWith(`/${assetName}.png`))),path=catalogItem?.assets?.[resolution]?.png||`${avatar.gender}/${resolution}/${layer}/${assetName}.png`;return avatarPngPaths.has(path)?path:null;}
function spriteLayerSource(layer,item,resolution){const path=['body','eyes','hair'].includes(layer)?creatorLayerPath(layer,item,resolution):itemLayerPath(layer,item,resolution);return versionedAvatarUrl(path);}
function avatarVariantForSize(sizeClass=''){return sizeClass?spriteManifest.compactResolution||'compact':spriteManifest.defaultResolution||'runtime';}
function spriteAvatar(item,sizeClass=''){
  const variantName=avatarVariantForSize(sizeClass),variant=spriteManifest.variants?.[variantName]||spriteManifest.variants.runtime,anchor=variant.anchor||{name:'feet-center',x:variant.width/2,y:variant.height},layers=spriteManifest.layerOrder.map((layer,index)=>{const source=spriteLayerSource(layer,item,variantName);return source?`<img class="avatar-layer avatar-layer-${layer}" data-avatar-layer="${layer}" src="${esc(source)}" width="${variant.width}" height="${variant.height}" style="--layer-index:${index+1}" alt="" draggable="false">`:'';}).join('');
  return `<div class="game-avatar sprite-avatar v4-production-avatar ${sizeClass}" data-sprite-avatar data-avatar-variant="${variantName}" role="img" aria-label="Avatar postaci"><div class="sprite-stage avatar-viewport" data-avatar-width="${variant.width}" data-avatar-height="${variant.height}" data-avatar-anchor-x="${anchor.x}" data-avatar-anchor-y="${anchor.y}" style="--sprite-ratio:${variant.width}/${variant.height}"><div class="avatar-canvas" data-avatar-canvas style="--avatar-native-width:${variant.width};--avatar-native-height:${variant.height}">${layers}</div><span class="sprite-placeholder"><strong>BRAK ASSETU</strong><small>CRESCI v4 · ${item.gender==='male'?'MALE':'FEMALE'}</small></span></div></div>`;
}
function hydrateSpriteStages(root=document){root.querySelectorAll('[data-sprite-avatar]').forEach(avatar=>{const stage=avatar.querySelector('.sprite-stage'),images=[...stage.querySelectorAll('img')],canvas=stage.querySelector('[data-avatar-canvas]');const updateScale=()=>{if(!canvas)return;const width=Number(stage.dataset.avatarWidth)||512,height=Number(stage.dataset.avatarHeight)||768,anchorY=Number(stage.dataset.avatarAnchorY)||height,scale=Math.min(stage.clientWidth/width,stage.clientHeight/height),anchorOffset=-(height-anchorY)*scale;stage.style.setProperty('--avatar-scale',String(scale));stage.style.setProperty('--avatar-anchor-offset',`${anchorOffset}px`);stage.dataset.avatarScale=String(scale);};const update=()=>{const failed=images.filter(image=>image.dataset.spriteFailed==='1').length,loaded=images.filter(image=>image.complete&&image.naturalWidth>0&&image.dataset.spriteFailed!=='1').length;stage.classList.toggle('assets-ready',images.length>0&&loaded===images.length&&failed===0);stage.classList.toggle('assets-missing',failed>0);updateScale();};for(const image of images){image.addEventListener('load',()=>{delete image.dataset.spriteFailed;image.hidden=false;update();});image.addEventListener('error',()=>{image.dataset.spriteFailed='1';image.hidden=true;update();});}update();if(canvas&&typeof ResizeObserver!=='undefined'){const observer=new ResizeObserver(updateScale);observer.observe(stage);stage._avatarResizeObserver=observer;}});}
function renderGameSettings(){const rows=state.data.game_settings||[];$('#gameSettingsList').innerHTML=rows.map(item=>`<div class="score-setting-row" data-game-setting="${item.user_id}"><div class="score-setting-user"><i style="background:${item.color}"></i><strong>${esc(item.user_name)}</strong>${item.avatar_configured?'<small>avatar gotowy</small>':''}</div><label class="score-switch"><input type="checkbox" data-game-enabled ${Number(item.enabled)?'checked':''}><span></span><b>${Number(item.enabled)?'ON':'OFF'}</b></label></div>`).join('');}
async function renderGame(){
  const enabledRows=(state.data.game_settings||[]).filter(item=>Number(item.enabled)),enabled=enabledRows.length>0;
  for(const id of ['characterNav','inventoryNav','shopNav','achievementsNav'])$(`#${id}`).hidden=!enabled;
  if(!enabled){
    state.gameResults=[];state.achievementResult=null;state.inventoryResult=null;state.shopResult=null;
    $('#characterGrid').innerHTML='';$('#achievementGroups').innerHTML='';$('#inventoryGrid').innerHTML='';$('#shopGrid').innerHTML='';
    if(['character','inventory','shop','achievements'].includes(state.view))switchView('dashboard');return;
  }
  for(const id of ['achievementProfile','inventoryProfile','shopProfile']){
    const select=$(`#${id}`),selected=select.value;select.innerHTML=enabledRows.map(item=>`<option value="${item.user_id}">${esc(item.user_name)}</option>`).join('');
    if(enabledRows.some(item=>String(item.user_id)===selected))select.value=selected;
  }
  try{
    state.gameResults=await api('/api/cresci-game');renderCharacters();
    if(state.view==='achievements')await renderAchievements();
    if(state.view==='inventory')await renderInventory();
    if(state.view==='shop')await renderShop();
  }catch(error){toast(error.message);}
}
function renderCharacters(){const grid=$('#characterGrid');grid.innerHTML=state.gameResults.map(item=>`<article class="character-card" style="--profile-color:${esc(item.color)}"><div class="character-hero">${spriteAvatar(item)}<div><span class="character-name">${esc(item.user_name)}</span><strong>Poziom ${item.level}</strong><small>${item.total_xp} XP łącznie</small></div></div><div class="xp-panel"><div><strong>XP do poziomu ${item.level+1}</strong><span>${item.current_xp} / ${item.required_xp}</span></div><div class="xp-bar"><i style="width:${item.progress_percent}%"></i></div></div><div class="game-actions"><button class="primary" type="button" data-game-check-in="${item.user_id}" ${item.checked_in_today?'disabled':''}>${item.checked_in_today?'✓ Zameldowano dzisiaj':`Zamelduj się · +${item.check_in_xp} XP`}</button><button class="secondary" type="button" data-edit-avatar="${item.user_id}">Edytuj avatar</button></div><div class="pr-panel"><div><span>PR balance</span><strong>${item.pr_balance}</strong></div><div><span>Łącznie zdobyto</span><strong>${item.pr_total_earned} PR</strong></div><small>Waluta jest gotowa na rekordy, osiągnięcia i przyszły sklep.</small></div></article>`).join('');hydrateSpriteStages(grid);}
