async function searchCatalog(){
  const query=$('#catalogQuery').value.trim(),button=$('#catalogSearch');
  if(query.length<2){$('#catalogStatus').textContent='Wpisz co najmniej 2 znaki.';return;}
  button.disabled=true;button.textContent='Szukam…';$('#catalogStatus').textContent='Pobieram wyniki z wger…';$('#catalogResults').innerHTML='';
  try{
    state.catalogResults=await api(`/api/catalog/exercises?q=${encodeURIComponent(query)}`);
    $('#catalogStatus').textContent=state.catalogResults.length?`Znaleziono: ${state.catalogResults.length}. Wybierz ćwiczenie, aby uzupełnić formularz.`:'Brak wyników. Spróbuj angielskiej nazwy lub krótszego hasła.';
    $('#catalogResults').innerHTML=state.catalogResults.map((item,index)=>`<button class="catalog-result" type="button" data-catalog-index="${index}"><span><strong>${esc(item.name)}</strong><small>${esc(item.category)}${item.muscles.length?` · ${esc(item.muscles.slice(0,3).join(', '))}`:''}${item.equipment.length?` · ${esc(item.equipment.join(', '))}`:''}</small></span><span>＋</span></button>`).join('');
  }catch(error){ $('#catalogStatus').textContent=error.message; }
  finally{button.disabled=false;button.textContent='Szukaj';}
}
function chooseCatalogExercise(index){
  const item=state.catalogResults[index],form=$('#exerciseForm');if(!item)return;
  const nameField=form.elements.namedItem('name'),categoryField=form.elements.namedItem('category'),loadModeField=form.elements.namedItem('load_mode');
  nameField.value=item.name;
  if(![...categoryField.options].some(option=>option.value===item.category)) categoryField.add(new Option(item.category,item.category));
  categoryField.value=item.category;loadModeField.value=item.load_mode;
  $('#exerciseDialogTitle').textContent='Dodaj z katalogu';
  $('#catalogStatus').textContent=`Wybrano „${item.name}”. Możesz poprawić nazwę, partię i sposób obciążenia przed zapisem.`;
  nameField.focus();
}

