$('#backupSettingsForm').onsubmit=async e=>{e.preventDefault();try{await saveBackupSettings();await renderBackupStatus();}catch(error){toast(error.message)}};$('#runBackupNow').onclick=async()=>{const button=$('#runBackupNow');try{button.disabled=true;button.textContent='Synchronizuję…';await saveBackupSettings(false);const result=await api('/api/backup/run',{method:'POST',body:'{}'});toast(result.errors?.length?result.last_message:'Kopia zapisana pomyślnie.');await renderBackupStatus();}catch(error){toast(error.message)}finally{button.disabled=false;button.textContent='↻ Synchronizuj teraz';}};
$('#refreshBackupList').onclick=()=>loadBackupFiles().catch(error=>toast(error.message));$('#restoreBackupSelect').onfocus=()=>loadBackupFiles().catch(error=>toast(error.message));
$('#restoreBackup').onclick=async()=>{const button=$('#restoreBackup'),selected=state.backupFiles[Number($('#restoreBackupSelect').value)];if(!selected)return;try{await loadBackupFiles();const file=state.backupFiles.find(item=>item.name===selected.name);if(!file){toast('Ta kopia została usunięta. Lista została odświeżona.');return;}if(!confirm(`Przywrócić kopię „${file.name}”?\n\nAktualne dane zostaną zastąpione. CRESCI najpierw automatycznie zapisze kopię bezpieczeństwa bieżącego stanu.`))return;button.disabled=true;button.textContent='Przywracam…';const result=await api('/api/backup/restore',{method:'POST',body:JSON.stringify({name:file.name,drive_id:file.local?null:file.drive_id})});await load();await renderBackupStatus();toast(`Przywrócono kopię. Wpisy: ${result.imported.entries}.`);}catch(error){toast(error.message)}finally{button.disabled=false;button.textContent='Przywróć wybraną kopię';}};
$('#configureDrive').onclick=openDriveWizard;$('#wizardNext').onclick=()=>showDriveWizardStep(Math.min(3,driveWizardStep+1));$('#wizardBack').onclick=()=>showDriveWizardStep(Math.max(1,driveWizardStep-1));$('#copyRedirectUri').onclick=async()=>{try{await navigator.clipboard.writeText($('#wizardRedirectUri').textContent);toast('Adres przekierowania skopiowany.');}catch{toast('Nie udało się skopiować — zaznacz adres ręcznie.');}};
$('#driveConfigForm').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,payload={client_id:form.elements.namedItem('client_id').value,client_secret:form.elements.namedItem('client_secret').value,redirect_uri:form.elements.namedItem('redirect_uri').value};try{$('#wizardSave').disabled=true;await api('/api/google-drive/config',{method:'POST',body:JSON.stringify(payload)});$('#driveConfigDialog').close();await renderBackupStatus();toast('Konfiguracja zapisana. Przechodzę do logowania Google…');setTimeout(()=>{location.href='/api/google-drive/connect';},500);}catch(error){toast(error.message)}finally{$('#wizardSave').disabled=false;}};
$('#connectDrive').onclick=()=>{location.href='/api/google-drive/connect';};$('#disconnectDrive').onclick=async()=>{if(!confirm('Odłączyć Google Drive? Lokalne kopie i pliki znajdujące się już na Dysku pozostaną bez zmian.'))return;try{await api('/api/google-drive/connection',{method:'DELETE'});await renderBackupStatus();toast('Google Drive został odłączony.');}catch(error){toast(error.message)}};
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&state.view==='settings'&&state.settingsTab==='backup')loadBackupFiles().catch(()=>{});});
loadSpriteManifest().then(showAuth).catch(err=>toast(err.message));
